    public record DiscrepancyRow(Long id, LocalDate bizDate, String txnNo, long amountCents, String reason) {
    }

    /**
     * 幂等记录行。
     */
    public record IdemRow(String scope, String requestId, String fingerprint, String responseBody) {
    }
}

