private ExitResponse doExit(ExitRequest request, String fp) {
    TxnRow txn = repository.findTxnByNoForUpdate(request.txnNo())
        .orElseThrow(() -> MetroException.notFound("TXN_NOT_FOUND", ...));
    if ("COMPLETED".equals(txn.status())) throw conflict TXN_ALREADY_COMPLETED;
    if (request.exitTime().isBefore(txn.entryTime())) throw badRequest EXIT_BEFORE_ENTRY;
    if (!mileageGraph.stationExists(request.station())) throw badRequest STATION_UNKNOWN;

    boolean compensated = "ESTIMATED".equals(txn.status());
    boolean lateDiscrepancy = false;

    if (compensated) {
        // 冲销暂记
        List<DetailRow> estimates = repository.findDetailsByTxnAndType(txn.txnNo(), "ESTIMATE");
        for (DetailRow est : estimates) {
            BatchRow estBatch = repository.findBatchById(est.batchId()).orElseThrow();
            if ("OPEN".equals(estBatch.status())) {
                repository.insertDetail(new DetailRow(null, est.batchId(), txn.txnNo(), est.lineCode(), est.distanceM(), est.ratio(), -est.amountCents(), "REVERSAL"));
            } else {
                repository.insertDiscrepancy(new DiscrepancyRow(null, estBatch.bizDate(), txn.txnNo(), -est.amountCents(), "REVERSAL_AFTER_SEAL"));
                lateDiscrepancy = true;
            }
        }
    }

    // 计费
    ShortestPath path = mileageGraph.shortestPath(txn.entryStation(), request.station());
    long distanceM = path.totalDistanceM();
    long chainBase = 0; boolean transfer = false;
    Optional<TxnRow> prev = repository.findLatestExitedTxnForCard(txn.cardId(), txn.entryTime());
    if (prev.isPresent()) {
        Duration gap = Duration.between(prev.get().exitTime(), txn.entryTime());
        if (!gap.isNegative() && gap.compareTo(TRANSFER_WINDOW) <= 0) {
            transfer = true;
            chainBase = prev.get().chainBaseM() + prev.get().distanceM();
        }
    }
    long normalFare = fareCalculator.fareCents(chainBase + distanceM) - fareCalculator.fareCents(chainBase);
    long penalty = 0;
    if (Duration.between(txn.entryTime(), request.exitTime()).compareTo(OVERTIME_LIMIT) > 0) {
        penalty = Math.max(0, maxNetworkFareCents() - normalFare);
    }
    long fare = normalFare + penalty;

    // 入账
    LocalDate bizDate = request.exitTime().toLocalDate();
    BatchRow batch = getOrCreateBatchForUpdate(bizDate);
    Long batchId = batch.id();
    if ("SEALED".equals(batch.status())) {
        repository.insertDiscrepancy(new DiscrepancyRow(null, bizDate, txn.txnNo(), fare, "LATE_AFTER_SEAL"));
        lateDiscrepancy = true;
        batchId = null;
    } else {
        String entryType = compensated ? "SETTLE" : "NORMAL";
        allocate(batch.id(), txn.txnNo(), path.lineDistanceM(), distanceM, fare, entryType);
    }

    TxnRow updated = new TxnRow(txn.id(), txn.txnNo(), txn.cardId(), txn.entryStation(), txn.entryTime(),
        request.station(), request.exitTime(), "COMPLETED", distanceM, chainBase, fare, penalty,
        transfer, false, batchId, bizDate, txn.requestId(), txn.fingerprint());
    repository.updateTxnSettlement(updated);
    return new ExitResponse(txn.txnNo(), "COMPLETED", distanceM, fare, penalty, transfer, compensated, bizDate.toString(), lateDiscrepancy, false);
}
